// Parse last-run timestamp and Awaiting Decision flags from Obsidian Housekeeping.md
const content = $input.item.json.body ?? $input.item.json.data ?? '';

// --- Parse last-run timestamp ---
// Looks for: **Last run:** 2026-05-06T06:00:00+12:00
// Treats missing, '—', or invalid values as 'not yet run' → falls back to 1 year ago
const oneYearAgo = new Date(Date.now() - 365 * 24 * 60 * 60 * 1000).toISOString();
const timestampMatch = content.match(/\*\*Last run:\*\*\s*([^\n]+)/);
let lastRun = null;
let lastRunIso = null;

if (timestampMatch) {
  const raw = timestampMatch[1].trim();
  if (raw === '—' || raw === '-' || raw === '') {
    // Explicit 'not yet run' sentinel
    lastRunIso = oneYearAgo;
    lastRun = 'NOT SET – fell back to 1 year ago';
  } else {
    const parsed = new Date(raw);
    if (!isNaN(parsed.getTime())) {
      lastRunIso = parsed.toISOString();
      lastRun = raw;
    } else {
      // Unrecognisable value — safe fallback
      lastRunIso = oneYearAgo;
      lastRun = `INVALID ("${raw}") – fell back to 1 year ago`;
    }
  }
} else {
  // No Last run line found at all
  lastRunIso = oneYearAgo;
  lastRun = 'NOT FOUND – fell back to 1 year ago';
}

// --- Parse Awaiting Decision flags ---
// Section sits between ## Awaiting Decision and the next ## heading
const awaitingSection = content.match(/## Awaiting Decision\n([\s\S]*?)(?=\n## |$)/);
const awaitingRaw = awaitingSection ? awaitingSection[1].trim() : '';

// Find all flag items — lines starting with - [ ] or - [x]
const flagPattern = /^- (\[[ x]\]) `([^`]+)` — (.+?)(?:\n(?:  .*)?)*$/gm;
const flags = [];
let match;

while ((match = flagPattern.exec(awaitingRaw)) !== null) {
  const checked = match[1] === '[x]';
  const filePath = match[2];
  const description = match[3];

  // Try to extract a decision note (lines indented under the flag)
  const flagStart = match.index;
  const flagEnd = flagStart + match[0].length;
  const afterFlag = awaitingRaw.slice(flagEnd);
  const decisionMatch = afterFlag.match(/^\n(?:  >\s*Decision:\s*([^\n]+)|  Decision:\s*([^\n]+))/);
  const decision = decisionMatch ? (decisionMatch[1] || decisionMatch[2] || '').trim() : null;

  flags.push({
    checked,
    filePath,
    description,
    decision,
    readyToAction: checked && decision !== null
  });
}

// Summary
const pendingCount = flags.filter(f => !f.checked).length;
const actionableCount = flags.filter(f => f.readyToAction).length;

console.log(`Last run: ${lastRun}`);
console.log(`Awaiting Decision flags: ${flags.length} total, ${actionableCount} actionable, ${pendingCount} pending`);

return [{
  lastRun,
  lastRunIso,
  awaitingFlags: flags,
  flagSummary: {
    total: flags.length,
    actionable: actionableCount,
    pending: pendingCount
  },
  runStarted: new Date().toISOString()
}];

// Parse SSH find output — one absolute path per line
// Strip vault prefix to get vault-relative paths, apply exclusion filter

const vaultPath = $('Config').item.json.vaultPath;
const excludedRaw = $('Config').item.json.excludedPaths ?? '';
const excludedPaths = typeof excludedRaw === 'string'
  ? excludedRaw.split(',').map(p => p.trim()).filter(p => p.length > 0)
  : excludedRaw;

const lastRunIso = $('Parse Timestamp & Flags').item.json.lastRunIso;

const stdout = $input.item.json.stdout ?? '';

// Split on newlines, drop empty lines
const absolutePaths = stdout.split('\n').map(l => l.trim()).filter(l => l.length > 0);

// Convert to vault-relative paths
const relativePaths = absolutePaths.map(p => {
  const prefix = vaultPath.endsWith('/') ? vaultPath : vaultPath + '/';
  return p.startsWith(prefix) ? p.slice(prefix.length) : p;
});

// Apply exclusion filter
const filtered = relativePaths.filter(filePath =>
  !excludedPaths.some(excluded => filePath.startsWith(excluded))
);

console.log(`Files modified since ${lastRunIso}: ${relativePaths.length}`);
console.log(`After exclusion filter: ${filtered.length}`);

return [{
  allFiles: relativePaths,
  filteredFiles: filtered,
  excludedCount: relativePaths.length - filtered.length,
  fileCount: filtered.length,
  lastRunIso
}];

// Build Log Entry
// Reads existing log, builds new entry, prepends it, trims to 10 days

const now = new Date();
const nzOffset = 12 * 60;
const nzDate = new Date(now.getTime() + nzOffset * 60 * 1000);
const datestamp = nzDate.toISOString().slice(0, 16).replace('T', ' | ');

// 10-day cutoff
const cutoff = new Date(now.getTime() - 10 * 24 * 60 * 60 * 1000);

const lastRun = $('Parse Timestamp & Flags').first().json.lastRun;
const flagSummary = $('Parse Timestamp & Flags').first().json.flagSummary;

// Aggregated file results
const allItems = $('Aggregate Results').first().json.data ?? [];
const fileCount = allItems.length;

const fixedLines = [];
const flaggedLines = [];

for (const item of allItems) {
  const name = item.filename ?? item.filePath ?? 'unknown';
  const fixes = item.fixes ?? [];
  const flags = item.flags ?? [];
  const writeStatus = item.writeStatus ?? 'unknown';

  if (fixes.length > 0) {
    for (const fix of fixes) {
      fixedLines.push(`- \`${name}\` — ${fix}`);
    }
    if (writeStatus !== 'written' && writeStatus !== 'skipped') {
      fixedLines.push(`  ⚠️ Write status: ${writeStatus}`);
    }
  }

  if (flags.length > 0) {
    for (const flag of flags) {
      flaggedLines.push(`- \`${name}\` — ${flag}`);
    }
  }

  // Unchanged files not logged
}

const fixedSection = fixedLines.length > 0
  ? `\n#### Fixed\n${fixedLines.join('\n')}`
  : '';

const flaggedSection = flaggedLines.length > 0
  ? `\n#### Flagged\n${flaggedLines.join('\n')}`
  : '';

const noActivity = fixedLines.length === 0 && flaggedLines.length === 0
  ? '\n*No fixes or flags this run.*'
  : '';

const newEntry = `### ${datestamp}\n**Last run read:** ${lastRun}\n**Files processed:** ${fileCount}\n**Awaiting Decision flags:** ${flagSummary.total} total (${flagSummary.actionable} actionable, ${flagSummary.pending} pending)${fixedSection}${flaggedSection}${noActivity}`;

// Read existing log
const existingLog = $input.item.json.body ?? $input.item.json.data ?? '';

// Split on the file header (frontmatter + title + related + summary + divider)
// Everything before '## Log' is the static header, everything after is entries
const logSectionMatch = existingLog.match(/^(---[\s\S]*?## Log\n)([\s\S]*)$/m);
const staticHeader = logSectionMatch ? logSectionMatch[1] : existingLog;
const existingEntries = logSectionMatch ? logSectionMatch[2] : '';

// Split existing entries by '### ' heading — each entry starts with ### YYYY-MM-DD
const entryBlocks = existingEntries.split(/(?=^### \d{4}-\d{2}-\d{2})/m).filter(e => e.trim());

// Filter to entries within 10 days
const recentEntries = entryBlocks.filter(block => {
  const dateMatch = block.match(/^### (\d{4}-\d{2}-\d{2})/);
  if (!dateMatch) return true; // keep non-standard entries (e.g. Manual session)
  const entryDate = new Date(dateMatch[1]);
  return entryDate >= cutoff;
});

// Normalise each entry: trim trailing whitespace/newlines, then join with exactly one blank line
const trimmedNew = newEntry.trimEnd();
const trimmedRecent = recentEntries.map(e => e.trimEnd());
const allEntries = [trimmedNew, ...trimmedRecent].join('\n\n');
const updatedLog = `${staticHeader}\n${allEntries}\n`;

console.log(`Log: prepended entry, kept ${recentEntries.length} existing entries, trimmed ${entryBlocks.length - recentEntries.length}`);

return [{ updatedContent: updatedLog }];

// Stage 2 — Mechanical Checks (Frontmatter + H1 + Intro Heading)
// Processes ALL items in one execution to avoid n8n single-item drop issue

// ── Schema definitions ────────────────────────────────────────────────────
// Required keys per type, in correct order (excluding date created/modified which Linter owns)
const SCHEMA = {
  project:  ['type', 'project', 'area', 'status'],
  research: ['type', 'project', 'area', 'status'],
  log:      ['type', 'project', 'area'],
  wiki:     ['type', 'area'],
  meta:     ['type', 'area'],
};

// Map filename prefixes to type values
const PREFIX_TO_TYPE = {
  'Project':  'project',
  'Research': 'research',
  'Wiki':     'wiki',
  'Log':      'log',
  'Meta':     'meta',
  'Area':     'area',
};

// Intro heading per type
const INTRO_HEADING = {
  project:  'Brief',
  research: 'Overview',
  wiki:     'Overview',
  log:      'Summary',
  meta:     null,
};

// Bad intro heading names that should be auto-corrected (not flagged)
const BAD_INTROS = ['Description', 'About', 'Introduction', 'Background', 'Summary', 'Brief', 'Overview'];

// ── Helper: toSlug ────────────────────────────────────────────────────────
// Strip a type prefix (e.g. "Project – ", "Research – ") then lowercase-hyphenate
function toSlug(str) {
  const prefixMatch = str.match(/^(?:Project|Research|Wiki|Log|Meta|Area)\s*[–-]\s*(.+)$/);
  const base = prefixMatch ? prefixMatch[1] : str;
  return base.trim().toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');
}

// ── Helper: parseFrontmatter ──────────────────────────────────────────────
// Returns { keys: {key: value}, order: [keys in file order], raw, fmEnd }
function parseFrontmatter(content) {
  const fmMatch = content.match(/^---(\n[\s\S]*?\n)---\n/);
  if (!fmMatch) return null;
  const raw = fmMatch[1];
  const fmEnd = fmMatch[0].length;
  const order = [];
  const keys = {};
  for (const line of raw.split('\n')) {
    const m = line.match(/^([\w ]+):\s*(.*)$/);
    if (m) {
      order.push(m[1]);
      keys[m[1]] = m[2].trim();
    }
  }
  return { keys, order, raw, fmEnd };
}

// ── Helper: buildFrontmatter ──────────────────────────────────────────────
// Reconstructs frontmatter block from an ordered array of [key, value] pairs
function buildFrontmatter(pairs) {
  const lines = pairs.map(([k, v]) => `${k}: ${v}`);
  return `---\n${lines.join('\n')}\n---\n`;
}

// ── Helper: getAllKnownFiles ───────────────────────────────────────────────
// Returns vault-relative paths from the SSH find stdout — used to locate
// sibling Project – files without a separate SSH call
function getAllKnownFiles() {
  try {
    const stdout = $('Find Modified Files (SSH)').first().json.stdout ?? '';
    const vaultPath = $('Config').first().json.vaultPath;
    const prefix = vaultPath.endsWith('/') ? vaultPath : vaultPath + '/';
    return stdout.split('\n')
      .map(l => l.trim())
      .filter(l => l.length > 0)
      .map(l => l.startsWith(prefix) ? l.slice(prefix.length) : l);
  } catch(e) {
    return [];
  }
}

// ── Main loop ─────────────────────────────────────────────────────────────

const results = [];
const allKnownFiles = getAllKnownFiles();
const prepareItems = $('Prepare File Item').all();

for (const [index, item] of $input.all().entries()) {
  const resolvedPath = prepareItems[index]?.json.filePath ?? null;
  const raw = item.json.data ?? item.json.body ?? '';

  if (!resolvedPath || !raw) {
    results.push({ json: {
      filePath: resolvedPath ?? `index:${index}`,
      filename: resolvedPath ? resolvedPath.split('/').pop().replace(/\.md$/, '') : `unknown-${index}`,
      fileType: null,
      content: raw,
      changed: false,
      fixes: [],
      flags: [],
      error: `Missing ${!resolvedPath ? 'filePath' : 'content'} at index ${index}`
    }});
    continue;
  }

  const filename = resolvedPath.split('/').pop().replace(/\.md$/, '');
  const pathParts = resolvedPath.split('/');
  const folderPath = pathParts.slice(0, -1).join('/');
  const parentFolder = pathParts.length >= 2 ? pathParts[pathParts.length - 2] : null;
  const isInProjectsRoot = pathParts.length === 2 && pathParts[0] === 'Projects';

  let content = raw;
  const fixes = [];
  const flags = [];

  // ──────────────────────────────────────────────────────────────
  // CHECK 1: Frontmatter
  // ──────────────────────────────────────────────────────────────
  const fm = parseFrontmatter(content);

  if (!fm) {
    flags.push('No frontmatter block found — skipping frontmatter checks');
  } else {
    const fmKeys = fm.keys;
    const fmOrder = fm.order;
    const fmEnd = fm.fmEnd;
    let fmChanged = false;

    // — 1a: Derive type if missing —
    let fileType = fmKeys['type'] ?? null;
    if (!fileType) {
      const prefixMatch = filename.match(/^([A-Za-z]+)\s*[–-]/);
      const derivedType = prefixMatch ? (PREFIX_TO_TYPE[prefixMatch[1]] ?? null) : null;
      if (derivedType) {
        fmKeys['type'] = derivedType;
        if (!fmOrder.includes('type')) fmOrder.unshift('type');
        fileType = derivedType;
        fixes.push(`Inserted missing frontmatter key: type: ${derivedType} (derived from filename prefix)`);
        fmChanged = true;
      } else {
        flags.push(`Cannot derive type from filename "${filename}" — manual review needed. Skipping remaining frontmatter checks.`);
      }
    }

    if (fileType && SCHEMA[fileType]) {
      const schemaKeys = SCHEMA[fileType];

      // — 1b: Derive project slug if missing —
      if (schemaKeys.includes('project') && !fmKeys['project']) {
        let derivedSlug = null;
        let derivedFrom = null;

        // Strategy 1: sibling Project – *.md in same folder
        const siblingProject = allKnownFiles.find(f => {
          const parts = f.split('/');
          const sibFolder = parts.slice(0, -1).join('/');
          const sibName = parts[parts.length - 1];
          return sibFolder === folderPath && /^Project\s*[–-]/.test(sibName);
        });

        if (siblingProject) {
          const sibName = siblingProject.split('/').pop().replace(/\.md$/, '');
          derivedSlug = toSlug(sibName);
          derivedFrom = `sibling file "${sibName}"`;
        } else if (!isInProjectsRoot && parentFolder && parentFolder !== 'Projects') {
          // Strategy 2: parent folder name
          derivedSlug = toSlug(parentFolder);
          derivedFrom = `parent folder "${parentFolder}"`;
        } else {
          // Strategy 3: own filename
          derivedSlug = toSlug(filename);
          derivedFrom = `own filename "${filename}"`;
        }

        if (derivedSlug) {
          fmKeys['project'] = derivedSlug;
          fixes.push(`Inserted missing frontmatter key: project: ${derivedSlug} (derived from ${derivedFrom})`);
          fmChanged = true;
        } else {
          flags.push(`Cannot derive project slug for "${filename}" — manual review needed`);
        }
      }

      // — 1c: Insert status: active if missing (project / research only) —
      if (schemaKeys.includes('status') && !fmKeys['status']) {
        fmKeys['status'] = 'active';
        fixes.push(`Inserted missing frontmatter key: status: active (default)`);
        fmChanged = true;
      }

      // — 1d: Flag area if missing — LLM pass will infer —
      if (schemaKeys.includes('area') && !fmKeys['area']) {
        flags.push(`Missing frontmatter key: area — passed to LLM pass for inference`);
      }

      // — 1e: Reorder frontmatter keys to match schema —
      // Linter-owned keys stay last in their current positions
      const linterKeys = fmOrder.filter(k => k === 'date created' || k === 'date modified');
      const nonLinterKeys = fmOrder.filter(k => k !== 'date created' && k !== 'date modified');

      const orderedKeys = [];
      for (const k of schemaKeys) {
        if (fmKeys[k] !== undefined) orderedKeys.push(k);
      }
      for (const k of nonLinterKeys) {
        if (!orderedKeys.includes(k)) orderedKeys.push(k);
      }
      for (const k of linterKeys) orderedKeys.push(k);

      const currentOrder = [...nonLinterKeys, ...linterKeys];
      const orderCorrect = currentOrder.every((k, i) => k === orderedKeys[i]) && currentOrder.length === orderedKeys.length;

      if (!orderCorrect) {
        fixes.push(`Reordered frontmatter keys to match schema for type:${fileType}`);
        fmChanged = true;
      }

      // — 1f: Rebuild frontmatter block if anything changed —
      if (fmChanged) {
        const pairs = orderedKeys.map(k => [k, fmKeys[k]]);
        const newFm = buildFrontmatter(pairs);
        content = newFm + content.slice(fmEnd);
      }
    }
  }

  // Re-parse after frontmatter changes for downstream checks
  const fmAfter = parseFrontmatter(content);
  const fileType = fmAfter?.keys?.['type'] ?? fm?.keys?.['type'] ?? null;
  const fmEnd2 = fmAfter?.fmEnd ?? fm?.fmEnd ?? 0;

  // ──────────────────────────────────────────────────────────────
  // CHECK 2: H1
  // ──────────────────────────────────────────────────────────────
  const h1Match = content.match(/^# (.+)$/m);
  if (!h1Match) {
    const insertion = `# ${filename}\n\n`;
    content = content.slice(0, fmEnd2) + insertion + content.slice(fmEnd2);
    fixes.push(`Inserted missing H1: "${filename}"`);
  } else {
    const h1Text = h1Match[1].trim();
    if (h1Text !== filename) {
      content = content.replace(/^# .+$/m, `# ${filename}`);
      fixes.push(`Corrected H1: "${h1Text}" → "${filename}"`);
    }
  }

  // ──────────────────────────────────────────────────────────────
  // CHECK 3: Intro heading
  // ──────────────────────────────────────────────────────────────
  const expectedIntro = fileType ? (INTRO_HEADING[fileType] ?? null) : null;
  if (expectedIntro) {
    const fmEnd3 = parseFrontmatter(content)?.fmEnd ?? fmEnd2;
    const bodyAfterFm = content.slice(fmEnd3);
    const firstH2Match = bodyAfterFm.match(/^## (.+)$/m);
    if (!firstH2Match) {
      flags.push(`No H2 sections found — cannot verify intro heading`);
    } else {
      const firstH2 = firstH2Match[1].trim();
      if (firstH2 !== expectedIntro && BAD_INTROS.includes(firstH2)) {
        const corrected = bodyAfterFm.replace(/^## .+$/m, `## ${expectedIntro}`);
        content = content.slice(0, fmEnd3) + corrected;
        fixes.push(`Corrected intro heading: "## ${firstH2}" → "## ${expectedIntro}"`);
      } else if (firstH2 !== expectedIntro) {
        flags.push(`Intro heading is "## ${firstH2}" — expected "## ${expectedIntro}" for type:${fileType}. Manual review needed.`);
      }
    }
  }

  // ──────────────────────────────────────────────────────────────
  // CHECK 4: Task heading backlinks
  // Project and research files only.
  // Any ## Tasks heading must be formatted as:
  //   ## Tasks – Doc Name [[Doc Name|↗️]]
  // Auto-fix: bare ## Tasks, ## Tasks – Name (no backlink), or wrong name.
  // Log/wiki files: flag if any tasks are present, do not fix.
  // ──────────────────────────────────────────────────────────────
  (function fixTaskHeadings() {
    const applyTypes = ['project', 'research'];
    const flagTypes  = ['log', 'wiki'];

    if (flagTypes.includes(fileType)) {
      if (/^- \[[ x]\]/m.test(content)) {
        flags.push(`Tasks found in ${fileType} file — log/wiki files should not contain tasks`);
      }
      return;
    }

    if (!applyTypes.includes(fileType)) return;

    const taskHeadingRe = /^(## Tasks)(?: – [^\n\[]*)?(?:\s*\[\[[^\]]*\]\])?$/gm;
    const correctHeading = `## Tasks – ${filename} [[${filename}|↗️]]`;

    let taskHeadingFound = false;
    const newContent = content.replace(taskHeadingRe, (match) => {
      taskHeadingFound = true;
      if (match.trim() === correctHeading) return match;
      fixes.push(`Fixed task heading: "${match.trim()}" → "${correctHeading}"`);
      return correctHeading;
    });

    if (taskHeadingFound) content = newContent;
  })();

  // ──────────────────────────────────────────────────────────────
  // CHECK 5: Task section position
  // Project and research files only.
  // The Tasks section must appear immediately after Brief/Overview.
  // Auto-fix: extract Tasks block and reinsert at the correct position.
  // Dividers are intentionally stripped here — Check 6 rebuilds them
  // cleanly on the final pass over the fully reordered content.
  // ──────────────────────────────────────────────────────────────
  (function fixTaskSectionPosition() {
    const applyTypes = ['project', 'research'];
    if (!applyTypes.includes(fileType)) return;

    const fmResult = parseFrontmatter(content);
    const fmEnd5 = fmResult ? fmResult.fmEnd : 0;
    const body = content.slice(fmEnd5);

    const introName = INTRO_HEADING[fileType];
    if (!introName) return;

    const h2Re = /^## .+$/gm;
    const h2Matches = [...body.matchAll(h2Re)];
    if (h2Matches.length < 2) return;

    const tasksIdx = h2Matches.findIndex(m => /^## Tasks/.test(m[0]));
    const introIdx  = h2Matches.findIndex(m => m[0].includes(`## ${introName}`));

    if (tasksIdx === -1 || introIdx === -1) return;
    if (tasksIdx === introIdx + 1) return; // already correct

    const firstH2Pos = h2Matches[0].index;
    const preamble = body.slice(0, firstH2Pos);

    // Slice body into per-section chunks, each starting at its H2 heading
    const sections = h2Matches.map((m, i) => {
      const start = m.index;
      const end = i + 1 < h2Matches.length ? h2Matches[i + 1].index : body.length;
      return body.slice(start, end);
    });

    // Strip all leading --- and surrounding blank lines from each section.
    // Check 6 (dividers) runs after this and rebuilds them correctly.
    const cleanSections = sections.map(s => s.replace(/^(?:\n*---\n+)+/, '').replace(/^\n+/, ''));

    // Reorder: pull Tasks out, reinsert after intro
    const tasksBlock = cleanSections.splice(tasksIdx, 1)[0];
    const adjustedIntroIdx = tasksIdx < introIdx ? introIdx - 1 : introIdx;
    cleanSections.splice(adjustedIntroIdx + 1, 0, tasksBlock);

    // Join sections with a single blank line between them — no --- yet,
    // Check 6 will add them in the correct positions
    const rebuiltBody = preamble + cleanSections.join('\n');

    const newContent = content.slice(0, fmEnd5) + rebuiltBody;
    if (newContent !== content) {
      content = newContent;
      fixes.push(`Moved Tasks section to immediately after ## ${introName}`);
    }
  })();

  // ──────────────────────────────────────────────────────────────
  // CHECK 6: H2 section dividers  (runs last — cleans up after all
  // structural changes above)
  // Rules:
  //   • --- between every H2 (not before the first)
  //   • No --- between H3s within the same H2 block
  //   • All auto-fix
  // ──────────────────────────────────────────────────────────────
  (function fixH2Dividers() {
    const fmResult = parseFrontmatter(content);
    const fmEnd6 = fmResult ? fmResult.fmEnd : 0;
    const bodyIn = content.slice(fmEnd6);
    const lines = bodyIn.split('\n');
    const out = [];
    let h2Seen = false;

    for (let i = 0; i < lines.length; i++) {
      const line = lines[i];
      const isH2 = /^## (?!#)/.test(line);
      const isH3 = /^### (?!#)/.test(line);

      if (isH2) {
        // Strip any trailing blanks and --- lines in any combination
        // e.g. ---\n\n--- or ---\n--- both get fully cleared
        let stripping = true;
        while (stripping) {
          stripping = false;
          while (out.length > 0 && out[out.length - 1].trim() === '') { out.pop(); stripping = true; }
          while (out.length > 0 && out[out.length - 1].trim() === '---') { out.pop(); stripping = true; }
        }
        if (h2Seen) {
          out.push('');
          out.push('---');
        } else {
          out.push('');
        }
        out.push(line);
        h2Seen = true;
      } else if (isH3) {
        let lookback = out.length - 1;
        while (lookback >= 0 && out[lookback].trim() === '') lookback--;
        if (lookback >= 0 && out[lookback].trim() === '---') {
          out.splice(lookback, out.length - lookback);
          out.push('');
        }
        out.push(line);
      } else {
        out.push(line);
      }
    }

    const bodyOut = out.join('\n');
    if (bodyOut !== bodyIn) {
      content = content.slice(0, fmEnd6) + bodyOut;
      fixes.push('Fixed H2 section dividers (--- between H2s; removed --- before H3s)');
    }
  })();

  // ──────────────────────────────────────────────────────────────
  // CHECK 7: Related section
  // Rules:
  //   • If Related block exists, fix formatting (plain **Related:**, one link per line)
  //   • Sub-document types (research, log, wiki, meta) with project: set must link
  //     to the sibling Project – *.md index if one exists in the same folder
  //   • Project index files (type: project) and files with no sibling Project –
  //     file are not checked for a project link
  //   • If Related block is missing entirely, skip — LLM pass generates it
  // ──────────────────────────────────────────────────────────────
  (function fixRelatedSection() {
    const fmResult = parseFrontmatter(content);
    const fmEndR = fmResult ? fmResult.fmEnd : 0;

    // Find **Related:** block anywhere in the body (not frontmatter)
    // Matches: **Related:** followed by one or more [[...]] lines
    const relatedBlockRe = /\n\*\*Related:\*\*\n(?:\[\[[^\]]+\]\]\n)+/;
    const relatedMatch = content.slice(fmEndR).match(relatedBlockRe);

    if (!relatedMatch) {
      // No Related block anywhere — hand off to LLM pass
      return;
    }

    const relatedRaw = relatedMatch[0]; // includes leading \n

    // Extract current links
    const linkRe = /\[\[([^\]]+)\]\]/g;
    const existingLinks = [...relatedRaw.matchAll(linkRe)].map(m => m[1]);

    // Determine whether a project index link is required
    const subDocTypes = ['research', 'log', 'wiki', 'meta'];
    let requiredProjectLink = null;

    if (subDocTypes.includes(fileType) && fmAfter?.keys?.['project']) {
      const siblingProject = allKnownFiles.find(f => {
        const parts = f.split('/');
        const sibFolder = parts.slice(0, -1).join('/');
        const sibName   = parts[parts.length - 1];
        return sibFolder === folderPath && /^Project\s*[–-]/.test(sibName);
      });
      if (siblingProject) {
        requiredProjectLink = siblingProject.split('/').pop().replace(/\.md$/, '');
      }
    }

    const projectLinked = requiredProjectLink
      ? existingLinks.some(l => l.split('|')[0].trim() === requiredProjectLink)
      : true;

    let links = [...existingLinks];
    if (!projectLinked) {
      links = [requiredProjectLink, ...links];
      fixes.push(`Added missing project index link to Related: [[${requiredProjectLink}]]`);
    }

    // Canonical Related block: \n\n**Related:**\n[[L1]]\n[[L2]]\n
    // Leading \n\n gives one blank line between H1 and **Related:**
    const canonicalBlock = `\n\n**Related:**\n${links.map(l => `[[${l}]]`).join('\n')}\n`;

    // Find the H1 line position — Related must sit immediately after it
    const h1Match = content.match(/^# .+$/m);
    if (!h1Match) return; // no H1, nothing to anchor to
    const h1End = content.indexOf(h1Match[0]) + h1Match[0].length;

    // Remove the existing Related block from wherever it currently is
    const bodyWithoutRelated = content.slice(fmEndR).replace(relatedRaw, '');

    // Check what's currently immediately after H1 in the stripped body
    const h1PosInStripped = bodyWithoutRelated.indexOf(h1Match[0]);
    const afterH1 = bodyWithoutRelated.slice(h1PosInStripped + h1Match[0].length);

    // Build corrected body: H1 + canonical Related + rest
    // Strip any leading blank lines from afterH1 — Related block provides its own
    const restOfBody = afterH1.replace(/^\n+/, '');
    const correctedBody = bodyWithoutRelated.slice(0, h1PosInStripped) +
      h1Match[0] + canonicalBlock + restOfBody;

    const newContent = content.slice(0, fmEndR) + correctedBody;

    if (newContent !== content) {
      const wasOutOfPlace = content.slice(h1End).search(relatedBlockRe) > 2;
      if (wasOutOfPlace) fixes.push('Moved Related section to immediately below H1');
      else if (canonicalBlock !== relatedRaw) fixes.push('Fixed Related section formatting');
      content = newContent;
    }
  })();

  const changed = content !== raw;
  console.log(`[${filename}] fixes: ${fixes.length}, flags: ${flags.length}, changed: ${changed}`);

  results.push({ json: {
    filePath: resolvedPath,
    filename,
    fileType,
    content,
    changed,
    fixes,
    flags
  }});
}

return results;

// ── LLM Pass (All-in-One) ─────────────────────────────────────────────────
// Receives all file items from Merge Branches.
// For each file: builds prompt, calls LM Studio, parses response, writes file if changed.
// All HTTP calls are made internally — no branching or merging needed.
// ─────────────────────────────────────────────────────────────────────────

const LLM_TYPES    = ['project', 'research', 'wiki', 'log'];
const modelName    = $('Config').first().json.manualModelName;
const obsidianBase = $('Config').first().json.obsidianBaseUrl ?? 'https://10.1.1.200:27124';

const SYSTEM_PROMPT = `You are a formatting assistant for an Obsidian vault. Fix structural and formatting issues only — never rewrite, summarise, or alter the substance of content.

Vault conventions:
- YAML frontmatter block: type, project, area, status keys
- H1 matches the filename exactly
- **Related:** section immediately below H1, one [[link]] per line, no aliases
- H2 sections are major topic breaks, separated by --- dividers (no --- before the first H2)
- H3 sections are genuine sub-sections within an H2, not standalone topics
- Tasks heading format: ## Tasks – Filename [[Filename|↗️]]

Your checks:
1. HEADING HIERARCHY — identify H3s used as standalone major topic breaks that should be H2s. Promote only when confidence is high. Flag if uncertain.
2. RELATED SECTION — if no **Related:** section exists immediately below H1, infer likely related documents from the area: and project: frontmatter values and any internal [[links]] in the document. Insert using correct format. If you cannot infer with confidence, do not insert.
3. CLARITY FLAGS — flag (do not fix) any section where the heading clearly does not match the content beneath it.

Strict rules:
- Never rewrite, expand, or summarise body content
- Never add links to area files in Related sections — area: values are category tags, not documents
- Never modify frontmatter values
- Never modify task content
- Return ONLY a JSON object, no preamble, no markdown fences:
{
  "content": "<full corrected document>",
  "fixes": ["one string per fix applied"],
  "flags": ["one string per flag for human review"]
}`;

const results = [];

for (const item of $input.all()) {
  const filePath    = item.json.filePath;
  const filename    = item.json.filename;
  const fileType    = item.json.fileType;
  const content     = item.json.content;
  const changed     = item.json.changed ?? false;
  const fixes       = [...(item.json.fixes ?? [])];
  const flags       = [...(item.json.flags ?? [])];
  const writeStatus = item.json.writeStatus ?? 'skipped';

  // Skip types that don't need the LLM pass
  if (!fileType || !LLM_TYPES.includes(fileType)) {
    results.push({ json: {
      filePath, filename, fileType, content, changed, fixes, flags,
      writeStatus, llmSkipped: true, llmChanged: false, llmError: null
    }});
    continue;
  }

  let llmContent = content;
  let llmFixes   = [];
  let llmFlags   = [];
  let llmError   = null;
  let llmChanged = false;

  // ── Call LM Studio ──────────────────────────────────────────────────
  try {
    const response = await $http.request({
      method: 'POST',
      url: 'http://10.1.1.200:1234/v1/chat/completions',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        model: modelName,
        temperature: 0.2,
        messages: [
          { role: 'system', content: SYSTEM_PROMPT },
          { role: 'user',   content: `Check this document and return the corrected version as JSON:\n\n${content}` }
        ]
      }),
      timeout: 600000
    });

    const rawText = response.choices?.[0]?.message?.content ?? '';
    const cleaned = rawText.replace(/^```json\s*/i, '').replace(/\s*```$/i, '').trim();
    const parsed  = JSON.parse(cleaned);

    if (!parsed.content || parsed.content.trim() === '') {
      llmError = 'LLM returned empty content — original preserved';
      flags.push(llmError);
    } else {
      llmContent = parsed.content;
      llmFixes   = Array.isArray(parsed.fixes) ? parsed.fixes : [];
      llmFlags   = Array.isArray(parsed.flags) ? parsed.flags : [];
      llmChanged = llmContent !== content;
    }

  } catch (err) {
    llmError = `LLM call failed: ${err.message}`;
    flags.push(llmError);
  }

  // ── Write to Obsidian if LLM changed the file ────────────────────────
  let finalWriteStatus = writeStatus;

  if (llmChanged) {
    try {
      const encodedPath = filePath.split('/').map(p => encodeURIComponent(p)).join('/');
      await $http.request({
        method: 'PUT',
        url: `${obsidianBase}/vault/${encodedPath}`,
        headers: {
          'Content-Type': 'text/markdown',
          'Authorization': $('Read Housekeeping.md').first().json.request?.headers?.Authorization ?? ''
        },
        body: llmContent,
        skipSslVerification: true
      });
      finalWriteStatus = 'written';
      console.log(`[${filename}] LLM changes written`);
    } catch (err) {
      llmError = `Write failed: ${err.message}`;
      flags.push(llmError);
      finalWriteStatus = 'write-failed';
      console.log(`[${filename}] Write failed: ${err.message}`);
    }
  }

  results.push({ json: {
    filePath,
    filename,
    fileType,
    content:     llmChanged ? llmContent : content,
    changed:     changed || llmChanged,
    fixes:       [...fixes, ...llmFixes],
    flags:       [...flags, ...llmFlags],
    writeStatus: finalWriteStatus,
    llmSkipped:  false,
    llmChanged,
    llmError
  }});
}

return results;
